#include "codegen_internal.h"

void cg_print_checked_operation(Ctx* ctx,
                                FILE* out,
                                const CgPlacement* placement,
                                IrInstruction* inst) {
  ctx->cg_state.builtin_label_id++;
  switch (inst->type) {
    case IR_INST_READ_INT:
    case IR_INST_READ_DOUBLE:
    case IR_INST_READ_BOOL:
    case IR_INST_READ_LINE:
      cg_print_io(ctx, out, placement, inst);
      break;

    case IR_INST_ORD:
    case IR_INST_STR_SUB:
    case IR_INST_CHR:
      cg_print_checked_string(ctx, out, placement, inst);
      break;

    default:
      break;
  }
}
